def _digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                     ensure_ascii=False).encode()).hexdigest()


def _apply(check_id, original, kind):
    row = ROWS.get(check_id)
    if row is None:
        return deepcopy(original)
    if not isinstance(original, dict) or _digest(original) != row[kind + "_base_sha256"]:
        raise ValueError("Reviewed Kubernetes clarity base changed: " + check_id + " (" + kind + ")")
    updated = deepcopy(original)
    from .k8s_native_review_copy_20261020 import reviewed_fields
    updated.update(reviewed_fields(check_id, kind, row[kind + "_fields"]))
    return updated


def description(check_id, original):
    return _apply(check_id, original, "description")


def remediation(check_id, original):
    return _apply(check_id, original, "remediation")


REVIEWED_RISKS = {check_id: (row["reviewed_source_severity"], row["reviewed_severity"])
                  for check_id, row in ROWS.items()}


def severity_review(check_id, source_severity):
    """Return the reviewed risk only while the original severity contract matches."""
    review = REVIEWED_RISKS.get(check_id)
    if review is None:
        return None
    if review[0] != source_severity:
        raise ValueError("Reviewed Kubernetes source severity changed: " + check_id)
    return review[1]
